{
  "name": "builder_stratified_rank_cap_safe_v2",
  "intuition": "For each batch element, sort candidates by objective (lower is better) and emit a small stratified set of comparisons (best-vs-middle, best-vs-worst, middle-vs-worst) to provide both easy and hard preferences while avoiding quadratic all-pairs.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, K = objective.shape

    # Clamp pairs_per_instance to [1, 3] without using Python int/max.
    ppi = extra.get('pairs_per_instance', 3)
    if ppi is None:
        ppi = 3
    if ppi < 1:
        ppi = 1
    if ppi > 3:
        ppi = 3

    if K <= 1:
        z = objective.new_zeros((0,), dtype=torch.long)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(z, z, z),
            weight=None,
            meta={'builder': 'stratified_rank_cap_safe_v2', 'pairs_per_instance': ppi}
        )

    order = objective.argsort(dim=1)  # [B, K]
    mid_r = K // 2
    tail_r = K - 1

    # Build pattern list without slicing (avoids potential restricted builtins usage).
    patterns = [(0, mid_r), (0, tail_r), (mid_r, tail_r)]
    if ppi == 1:
        patterns = [(0, tail_r)]
    elif ppi == 2:
        patterns = [(0, mid_r), (0, tail_r)]

    P = B * len(patterns)
    b_idx = torch.empty((P,), device=objective.device, dtype=torch.long)
    w_idx = torch.empty((P,), device=objective.device, dtype=torch.long)
    l_idx = torch.empty((P,), device=objective.device, dtype=torch.long)

    t = 0
    for b in range(B):
        row = order[b]
        for ra, rb in patterns:
            # Winner has lower objective => better (smaller rank index).
            w = row[ra]
            l = row[rb]
            b_idx[t] = b
            w_idx[t] = w
            l_idx[t] = l
            t = t + 1

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, w_idx, l_idx),
        weight=None,
        meta={'builder': 'stratified_rank_cap_safe_v2', 'pairs_per_instance': ppi}
    )
"
