{
  "name": "builder_gap_threshold_weight_001",
  "intuition": "Filters out near-ties and upweights clearer wins by using an objective-gap threshold; this reduces noisy preference pairs and emphasizes more reliable training signal.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # Only keep pairs with sufficient objective separation (lower is better).
    gap_threshold = extra.get('gap_threshold', 0.0) if extra is not None else 0.0
    # gap[i,j] = objective[j] - objective[i]; positive => i better than j
    gap = objective[:, None, :] - objective[:, :, None]
    mask = gap > gap_threshold
    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)
    if b_idx.numel() == 0:
        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'gap_threshold_weight', 'gap_threshold': float(gap_threshold)})
    # Nonnegative weights based on how far above the threshold the gap is.
    w = (gap[b_idx, winner_idx, loser_idx] - gap_threshold).clamp_min(0.0)
    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=w, meta={'builder': 'gap_threshold_weight', 'gap_threshold': float(gap_threshold)})
"
