{
  "name": "builder_gap_threshold_weight_001_fixfloat",
  "intuition": "Selects only unambiguous wins where the lower-is-better objective difference exceeds a configurable threshold, and weights each pair by how far beyond the threshold it is to emphasize clearer, more reliable comparisons.",
  "implementation_hint": {
