{
  "name": "loss_logsigmoid_consensus_margin_cost",
  "intuition": "All parents share a stable, well-behaved pairwise preference objective: take the log-probability gap (log_prob_w - log_prob_l), scale it, clamp for numerical stability, and apply -logsigmoid so increasing the win-gap decreases loss smoothly. A minority variant also subtracts a small detached cost gap; we keep this as an optional, safely gated margin term so it can encourage cost-aware ranking when cost signals exist without letting gradients flow into costs or breaking batches that lack cost fields. A small positive margin further stabilizes training by reducing ambiguity around near-ties.",
  "pseudocode": "d = lpw - lpl; margin = m0 + m_cost * detach(cost_b - cost_a if present else 0); x = clamp(alpha*scale*d - margin, -20, 20); loss = -logsigmoid(x); return mean(weight*loss if weight else loss)",
  "hyperparams": {
    "scale": 1.2,
    "base_margin": 0.0,
    "cost_margin_scale": 0.1
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch.get('weight', None)

    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}
    alpha = float(extra.get('alpha', hp.get('alpha', 1.0))) if isinstance(extra, dict) else 1.0
    scale = float(hp.get('scale', 1.2))
    base_margin = float(hp.get('base_margin', 0.0))
    cost_margin_scale = float(hp.get('cost_margin_scale', 0.1))

    d = lpw - lpl

    # Optional detached cost-based margin; defaults to 0 if costs are absent.
    if ('cost_a' in batch) and ('cost_b' in batch):
        cost_gap = (batch['cost_b'] - batch['cost_a']).detach()
        margin = base_margin + cost_margin_scale * cost_gap
    else:
        margin = base_margin

    x = alpha * scale * d - margin
    x = ops.clamp(x, -20.0, 20.0)
    loss = -ops.logsigmoid(x)
    if weight is not None:
        loss = loss * weight
    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry) preference loss on the win/lose log-probability gap with clamping for numerical stability; optional detached cost-based margin adds a fixed (non-learned) shift to reflect external preference strength without introducing gradients through costs.",
  "implementation_hint": {
    "expects": {
      "batch": "dict with keys 'log_prob_w' and 'log_prob_l' (tensor-like); optional 'weight' (nonnegative tensor broadcastable), optional 'cost_a'/'cost_b' (tensor-like)",
