  "name": "loss_logsigmoid_001_label_smooth",
  "intuition": "Add small label-smoothing by mixing the standard -logsigmoid(x) with its symmetric counterpart -logsigmoid(-x). This prevents extreme confidence on noisy preference pairs and improves stability/generalization while keeping the same pairwise ranking structure.",
  "pseudocode": "x = clamp(alpha*scale*(lpw-lpl), -20, 20)\nloss_pos = -logsigmoid(x)\nloss_neg = -logsigmoid(-x)\nloss = (1-eps)*loss_pos + eps*loss_neg",
  "hyperparams": {
