  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {})\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))\n    scale = float(hp.get('scale', 1.935399683524108))\n    eps = float(hp.get('label_smooth_eps', 0.05))\n\n    x = alpha * scale * (lpw - lpl)\n    x = ops.clamp(x, -20.0, 20.0)\n\n    loss_pos = -ops.logsigmoid(x)\n    loss_neg = -ops.logsigmoid(-x)\n    loss = (1.0 - eps) * loss_pos + eps * loss_neg\n\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry) loss with label smoothing: mixing the target preference probability away from 1.0 reduces overconfidence and can improve robustness to noisy/ambiguous comparisons.",
  "implementation_hint": {
